158	function writeToCache<T extends object>(cachePath: string, data: T) {
159	  const maxAttempts = 5;
160	  for (let attempt = 0; attempt < maxAttempts; attempt++) {
161	    const unique = (Math.random().toString(16) + '00000000').slice(2, 10);
162	    const tempPath = `${cachePath}.${process.pid}.${unique}.tmp`;
163	    try {
